    [Fact]
    public void RoundtripJson()
    {
        // Test that FromJson -> ToJson -> FromJson produces equivalent data
        string jsonData = """
{
  "kind": "failure",
  "failure": {
    "outcome": "indeterminate",
    "message": "SSE stream error: connection reset"
  }
}
